use neo4j::Session;
use neo4j::types::Value;
use neo4j::query::Query;

pub struct GraphDatabase {
    session: Session,
}

impl GraphDatabase {
    pub fn new(uri: &str, user: &str, password: &str) -> Self {
        let session = Session::builder(uri, user, password)
            .expect("Failed to create Neo4j session");
        GraphDatabase { session }
    }

    pub fn store_data(&self, sensor_id: &str, value: &str, timestamp: &str) {
        let query = Query::new("CREATE (s:Sensor {id: $id, value: $value, timestamp: $timestamp})");
        let params = HashMap::from([
            ("id", Value::String(sensor_id.to_string())),
            ("value", Value::String(value.to_string())),
            ("timestamp", Value::String(timestamp.to_string())),
        ]);

        self.session.run(&query, &params).expect("Failed to store data in Neo4j");
    }
}
